<?php
declare(strict_types=1);namespace App\Services;use PDO;
final class ExportService {public function __construct(private PDO $db){}public function create(int $tid,?int $uid,string $type):int{$s=$this->db->prepare('INSERT INTO export_jobs(user_id,tournament_id,export_type,status,progress,created_at) VALUES(?,?,?,"queued",0,NOW())');$s->execute([$uid,$tid,$type]);return(int)$this->db->lastInsertId();}public function run(int $id):string{try{$s=$this->db->prepare('SELECT * FROM export_jobs WHERE id=?');$s->execute([$id]);$j=$s->fetch()?:throw new \RuntimeException('Exportacao inexistente.');$this->db->prepare('UPDATE export_jobs SET status="processing",progress=10 WHERE id=?')->execute([$id]);$csv=$this->csv((int)$j['tournament_id'],$j['export_type']);$dir=dirname(__DIR__,2).'/storage/exports';if(!is_dir($dir))mkdir($dir,0750,true);$ext=str_starts_with($j['export_type'],'zip_')?'zip':'csv';$path='exports/'.bin2hex(random_bytes(12)).'.'.$ext;if($ext==='zip'){$z=new \ZipArchive();$z->open(dirname(__DIR__,2).'/storage/'.$path,\ZipArchive::CREATE);$z->addFromString('relatorio.csv',$csv);$z->close();}else file_put_contents(dirname(__DIR__,2).'/storage/'.$path,$csv);$this->db->prepare('UPDATE export_jobs SET status="completed",progress=100,file_path=?,completed_at=NOW(),expires_at=DATE_ADD(NOW(),INTERVAL 24 HOUR) WHERE id=?')->execute([$path,$id]);return$path;}catch(\Throwable $e){$this->db->prepare('UPDATE export_jobs SET status="failed",error_message=?,progress=0 WHERE id=?')->execute([$e->getMessage(),$id]);throw$e;}}private function csv(int $id,string $type):string{$map=['teams'=>'SELECT t.id,t.name,t.short_name,t.status FROM teams t JOIN team_tournament_entries e ON e.team_id=t.id WHERE e.tournament_id=? AND t.deleted_at IS NULL','athletes'=>'SELECT p.id,COALESCE(p.public_name,p.full_name) athlete,t.name team,r.status FROM registrations r JOIN people p ON p.id=r.person_id JOIN teams t ON t.id=r.team_id WHERE r.tournament_id=? AND r.registration_type="athlete"','matches'=>'SELECT id,status,scheduled_at,home_score,away_score FROM matches WHERE tournament_id=? AND deleted_at IS NULL','standings'=>'SELECT s.position,t.name,s.played,s.wins,s.draws,s.losses,s.goals_for,s.goals_against,s.points FROM standings_snapshots s JOIN teams t ON t.id=s.team_id WHERE s.tournament_id=? ORDER BY s.position','documents'=>'SELECT id,title,document_category,visibility,status FROM documents WHERE tournament_id=? AND deleted_at IS NULL','transfers'=>'SELECT id,status,movement_type,reason FROM transfers WHERE tournament_id=? AND deleted_at IS NULL'];$sql=$map[str_replace('zip_','',$type)]??$map['standings'];$s=$this->db->prepare($sql);$s->execute([$id]);$h=fopen('php://temp','w+');$first=true;foreach($s as$r){if($first){fputcsv($h,array_keys($r));$first=false;}fputcsv($h,$r);}rewind($h);return stream_get_contents($h);}}
